function ld_side(npc)
	local m, x, y = 0, 0, 0
	if npc and npc > 0 then m, x, y = GetNpcPos(npc) end
	if x == nil or x <= 0 then m, x, y = GetWorldPos() end
	if x < 1800 then return 2 end
	return 1
end

function main(npc)
	local side = ld_side(npc)
	local m = GetTask(PTTM_T_MAIN)
	if side == 1 and m >= 8 and m <= 12 then
		ld_main(m, 1)
		return
	end
	if side == 2 and m >= 15 and m <= 19 then
		ld_main(m, 2)
		return
	end
	ld_96()
end

function ld_lamps()
	local mk = PTTM_Get(F_LAMP)
	local c, b = 0, 1
	while b <= 32 do
		if PTTM_Bit(mk, b) == 1 then c = c + 1 end
		b = b * 2
	end
	return c
end

